part1 "" n = n
part1 (x:xs) n
  | x == '(' = part1 xs (n + 1)
  | x == ')' = part1 xs (n - 1)

part2 _ n (-1) = n
part2 (x:xs) n m
  | x == '(' = part2 xs (n + 1) (m + 1)
  | x == ')' = part2 xs (n + 1) (m - 1)

main :: IO ()
main = do
    putStrLn $ show $ part1 str 0
    putStrLn $ show $ part2 str 0 0

